    lodgepolePine_stage03Var2 = CONTRACTOR_LODGEPOLE_PINE_STAGE03VAR2_POINTS,
    pinusSylvestris_stage01 = CONTRACTOR_PINUS_SYLVESTRIS_01_POINTS,
    pinusSylvestris_stage02 = CONTRACTOR_PINUS_SYLVESTRIS_02_POINTS,
    pinusSylvestris_stage03 = CONTRACTOR_PINUS_SYLVESTRIS_03_POINTS,
    pinusSylvestris_stage04 = CONTRACTOR_PINUS_SYLVESTRIS_04_POINTS,
    pinusSylvestris_stage05 = CONTRACTOR_PINUS_SYLVESTRIS_05_POINTS,
    pinusTabuliformis_stage01 = CONTRACTOR_PINUS_TABULIFORMIS_01_POINTS,
    pinusTabuliformis_stage02 = CONTRACTOR_PINUS_TABULIFORMIS_02_POINTS,
    pinusTabuliformis_stage03 = CONTRACTOR_PINUS_TABULIFORMIS_03_POINTS,
    pinusTabuliformis_stage04 = CONTRACTOR_PINUS_TABULIFORMIS_04_POINTS,
    pinusTabuliformis_stage05 = CONTRACTOR_PINUS_TABULIFORMIS_05_POINTS,
    oak_stage01 = CONTRACTOR_OAK_STAGE01_POINTS,
    oak_stage02 = CONTRACTOR_OAK_STAGE02_POINTS,
    oak_stage03 = CONTRACTOR_OAK_STAGE03_POINTS,
    oak_stage04 = CONTRACTOR_OAK_STAGE04_POINTS,
    oak_stage05 = CONTRACTOR_OAK_STAGE05_POINTS,
    deadwood = CONTRACTOR_DEADWOOD_POINTS,
    treePineRavaged_big = CONTRACTOR_RAVAGED_BIG_POINTS,
    betulaErmanii_stage01 = CONTRACTOR_BETULA_ERMANII_01_POINTS,
    betulaErmanii_stage02 = CONTRACTOR_BETULA_ERMANII_02_POINTS,
    betulaErmanii_stage03 = CONTRACTOR_BETULA_ERMANII_03_POINTS,
    betulaErmanii_stage04 = CONTRACTOR_BETULA_ERMANII_04_POINTS,
    beech_stage01 = CONTRACTOR_BEECH_STAGE01_POINTS,
    beech_stage02 = CONTRACTOR_BEECH_STAGE02_POINTS,
    beech_stage02_var02 = CONTRACTOR_BEECH_STAGE02_VAR02_POINTS,
    beech_stage02_var03 = CONTRACTOR_BEECH_STAGE02_VAR03_POINTS,
